test -f supabase/migrations/0198_line_oa_revoke_client_write_grants.sql
# Require the entire target scope, not only an empty set of violations.
psql "postgresql://postgres@127.0.0.1:55450/postgres" -X -v ON_ERROR_STOP=1 -tAc "with targets as (select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('line_oa_channels','line_oa_conversations','line_oa_inbound_messages','line_oa_outbound_messages','line_oa_customer_identity','line_oa_message_templates','line_oa_orders','line_oa_audit_log')), clients as (select oid from pg_roles where rolname in ('anon','authenticated','service_role')) select (select count(*)=8 from targets) and (select count(*)=3 from clients) and not exists (select 1 from targets t cross join clients r where has_table_privilege(r.oid,t.oid,'INSERT') or has_table_privilege(r.oid,t.oid,'UPDATE') or has_table_privilege(r.oid,t.oid,'DELETE') or has_table_privilege(r.oid,t.oid,'TRUNCATE') or has_any_column_privilege(r.oid,t.oid,'INSERT') or has_any_column_privilege(r.oid,t.oid,'UPDATE'))" | grep -qx t
